svg.metadata:
flowchart TB
  A["Native environment: push.register({ signal? })"]
  B["Load plugin; request push permission"]
  C["Listen for registration / registrationError first"]
  D["Trigger native register; await actual event"]
  E["Dispose listeners; return HaiResult with token"]
  X["Denied / timeout / cancel / close: clean up and fail"]
  A --> B
  B -->|"granted"| C
  B -->|"denied / unavailable"| X
  C --> D
  D -->|"token received"| E
  E -->|"cleanup fails"| X
  D -->|"error / interruption"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
